#!/usr/bin/env python3import argparseimport csvimport mathimport sysfrom pathlib import Pathimport torchROOT_DIR = Path(__file__).resolve().parents[1]if str(ROOT_DIR) not in sys.path:    sys.path.insert(0, str(ROOT_DIR))from analysis.recompute_transfer_metrics import (  # noqa: E402    build_dataset,    build_loader,    build_model,    get_task_classes,    load_checkpoint,)STAGE_JOB_FIELDS = [    "task",    "source_dataset",    "target_dataset",    "seed",    "config",    "reshaper",    "strength",    "trainable",    "init_seed",    "reg_trade_off",    "dual_relation",    "source_intra",    "da_intra",    "structure_target",    "detach_features",    "est_weight",]def read_tsv(path):    with Path(path).open("r", encoding="utf-8", newline="") as handle:        return list(csv.DictReader(handle, delimiter="\t"))def read_jobs_tsv(path):    rows = []    with Path(path).open("r", encoding="utf-8", newline="") as handle:        reader = csv.reader(handle, delimiter="\t")        for parts in reader:            if not parts or parts[0] == "task":                continue            row = {field: parts[idx] if idx < len(parts) else "" for idx, field in enumerate(STAGE_JOB_FIELDS)}            rows.append(row)    return rowsdef write_tsv(path, rows, fields):    path = Path(path)    path.parent.mkdir(parents=True, exist_ok=True)    with path.open("w", encoding="utf-8", newline="\n") as handle:        writer = csv.DictWriter(handle, delimiter="\t", fieldnames=fields)        writer.writeheader()        for row in rows:            writer.writerow({field: format_value(row.get(field)) for field in fields})def format_value(value):    if value is None:        return ""    if isinstance(value, float):        if math.isnan(value) or math.isinf(value):            return ""        return f"{value:.8f}"    return str(value)def parse_csv_set(text):    if text is None or str(text).strip() == "":        return None    return {part.strip() for part in str(text).split(",") if part.strip()}def safe_float(value):    if value is None:        return None    text = str(value).strip()    if text == "":        return None    try:        return float(text)    except ValueError:        return Nonedef mean(values):    values = [value for value in values if value is not None]    return None if not values else sum(values) / len(values)def stdev(values):    values = [value for value in values if value is not None]    if len(values) < 2:        return None    avg = mean(values)    return math.sqrt(sum((value - avg) ** 2 for value in values) / (len(values) - 1))def task_seed_pairs(jobs, tasks, seeds, base_config, shaped_config):    tasks = parse_csv_set(tasks)    seeds = parse_csv_set(seeds)    by_key = {}    for row in jobs:        if tasks is not None and row["task"] not in tasks:            continue        if seeds is not None and row["seed"] not in seeds:            continue        if row["config"] not in {base_config, shaped_config}:            continue        by_key[(row["task"], row["seed"], row["config"])] = row    pairs = []    pair_keys = sorted({(task, seed) for task, seed, _ in by_key})    for task, seed in pair_keys:        base = by_key.get((task, seed, base_config))        shaped = by_key.get((task, seed, shaped_config))        if base is None or shaped is None:            continue        pairs.append((base, shaped))    return pairsdef source_model_name(row, args):    source_tile = row["source_dataset"].split("/")[1]    tag = f"{args.source_tag_prefix}_{row['task']}_seed{row['seed']}_{row['config']}"    return f"pseltae_{source_tile}_closedset_noshift_sourcephasecompact_p5_{tag}"def load_model_for_job(row, args, device):    experiment = source_model_name(row, args)    checkpoint_path = Path(args.outputs_root) / experiment / "fold_0" / "model.pt"    if not checkpoint_path.exists():        return None, [], checkpoint_path    classes = get_task_classes(args.data_root, row["source_dataset"], closed_set=True)    model = build_model(args.model, len(classes), args.with_extra, device)    load_checkpoint(model, checkpoint_path, device)    return model, classes, checkpoint_path@torch.no_grad()def collect_raw_features(model, loader, device, max_batches):    features = []    labels = []    for batch_idx, sample in enumerate(loader):        if max_batches > 0 and batch_idx >= max_batches:            break        pixels = sample["pixels"].to(device=device, non_blocking=True)        valid_pixels = sample["valid_pixels"].to(device=device, non_blocking=True)        extra = sample["extra"].to(device=device, non_blocking=True)        raw = model.spatial_encoder(pixels, valid_pixels, extra)        features.append(raw.detach().cpu().float())        labels.append(sample["label"].detach().cpu().long())    if not features:        return None, None    return torch.cat(features, dim=0), torch.cat(labels, dim=0)def class_time_compactness(features, labels):    total = 0.0    count = 0    for label in torch.unique(labels):        group = features[labels == label]        if group.numel() == 0:            continue        centroid = group.mean(dim=0, keepdim=True)        sq = (group - centroid).pow(2).mean(dim=-1)        total += float(sq.sum().item())        count += int(sq.numel())    return None if count == 0 else total / countdef pooled_intra_variance(features, labels):    pooled = features.mean(dim=1)    total = 0.0    count = 0    for label in torch.unique(labels):        group = pooled[labels == label]        if group.numel() == 0:            continue        centroid = group.mean(dim=0, keepdim=True)        sq = (group - centroid).pow(2).mean(dim=-1)        total += float(sq.sum().item())        count += int(sq.numel())    return None if count == 0 else total / countdef class_prototypes(features, labels):    pooled = features.mean(dim=1)    prototypes = []    for label in sorted(torch.unique(labels).tolist()):        prototypes.append(pooled[labels == label].mean(dim=0))    return torch.stack(prototypes, dim=0)def pairwise_sq_dists(x, y):    return ((x[:, None, :] - y[None, :, :]) ** 2).sum(dim=-1).clamp_min(0.0)def target_to_source_margin(source_features, source_labels, target_features, eps=1e-12):    prototypes = class_prototypes(source_features, source_labels)    target_pooled = target_features.mean(dim=1)    if prototypes.shape[0] < 2 or target_pooled.shape[0] == 0:        return None    dists = pairwise_sq_dists(target_pooled, prototypes)    nearest = torch.topk(dists, k=2, dim=1, largest=False).values    raw_margin = nearest[:, 1] - nearest[:, 0]    proto_dists = pairwise_sq_dists(prototypes, prototypes)    mask = ~torch.eye(prototypes.shape[0], dtype=torch.bool)    scale = proto_dists[mask].mean().clamp_min(eps)    return float((raw_margin / scale).mean().item())def compute_metrics_for_job(row, args, device):    model, classes, checkpoint_path = load_model_for_job(row, args, device)    base = {        "task": row["task"],        "seed": row["seed"],        "config": row["config"],        "checkpoint": str(checkpoint_path),    }    if model is None:        base["status"] = "missing_checkpoint"        return base    source_ds = build_dataset(args.data_root, row["source_dataset"], classes, True, args.with_extra)    target_ds = build_dataset(args.data_root, row["target_dataset"], classes, True, args.with_extra)    source_loader = build_loader(source_ds, args.batch_size, args.num_workers)    target_loader = build_loader(target_ds, args.batch_size, args.num_workers)    source_features, source_labels = collect_raw_features(model, source_loader, device, args.max_batches)    target_features, _ = collect_raw_features(model, target_loader, device, args.max_batches)    if source_features is None or target_features is None:        base["status"] = "empty_loader"        return base    base.update(        {            "status": "ok",            "source_count": int(source_features.shape[0]),            "target_count": int(target_features.shape[0]),            "source_raw_compactness": class_time_compactness(source_features, source_labels),            "source_pooled_intra_variance": pooled_intra_variance(source_features, source_labels),            "target_to_source_margin": target_to_source_margin(                source_features, source_labels, target_features            ),        }    )    return basedef summary_map(summary_rows):    out = {}    for row in summary_rows:        if row.get("status") not in ("ok", ""):            continue        out[(row.get("task"), str(row.get("seed")), row.get("config"))] = row    return outdef metric_delta(metric_map, task, seed, shaped_config, base_config, field):    shaped = metric_map.get((task, seed, shaped_config))    base = metric_map.get((task, seed, base_config))    if shaped is None or base is None:        return None    left = safe_float(shaped.get(field))    right = safe_float(base.get(field))    if left is None or right is None:        return None    return left - rightdef f1_delta(summary, task, seed, shaped_config, base_config):    shaped = summary.get((task, seed, shaped_config))    base = summary.get((task, seed, base_config))    if shaped is None or base is None:        return None, None, None    shaped_f1 = safe_float(shaped.get("da_f1"))    base_f1 = safe_float(base.get("da_f1"))    if shaped_f1 is None or base_f1 is None:        return shaped_f1, base_f1, None    return shaped_f1, base_f1, shaped_f1 - base_f1def sign(value, eps=1e-8):    if value is None:        return None    if value > eps:        return 1    if value < -eps:        return -1    return 0def same_direction(left, right):    left_sign = sign(left)    right_sign = sign(right)    if left_sign is None or right_sign is None:        return None    if left_sign == 0 or right_sign == 0:        return int(left_sign == right_sign)    return int(left_sign == right_sign)def build_chain_rows(metric_rows, summary_rows, args):    metrics = {        (row["task"], str(row["seed"]), row["config"]): row        for row in metric_rows        if row.get("status") == "ok"    }    summary = summary_map(summary_rows)    keys = sorted({(task, seed) for task, seed, config in metrics if config == args.base_config})    rows = []    for task, seed in keys:        if (task, seed, args.shaped_config) not in metrics:            continue        shaped_f1, base_f1, delta_f1 = f1_delta(summary, task, seed, args.shaped_config, args.base_config)        delta_compact = metric_delta(            metrics, task, seed, args.shaped_config, args.base_config, "source_raw_compactness"        )        delta_intra = metric_delta(            metrics, task, seed, args.shaped_config, args.base_config, "source_pooled_intra_variance"        )        delta_margin = metric_delta(            metrics, task, seed, args.shaped_config, args.base_config, "target_to_source_margin"        )        rows.append(            {                "task": task,                "seed": seed,                "base_config": args.base_config,                "shaped_config": args.shaped_config,                "base_da_f1": base_f1,                "shaped_da_f1": shaped_f1,                "delta_da_f1": delta_f1,                "delta_source_raw_compactness": delta_compact,                "delta_source_pooled_intra_variance": delta_intra,                "delta_target_to_source_margin": delta_margin,                "compactness_reduced": None if delta_compact is None else int(delta_compact < 0),                "intra_variance_reduced": None if delta_intra is None else int(delta_intra < 0),                "margin_increased": None if delta_margin is None else int(delta_margin > 0),                "margin_f1_same_direction": same_direction(delta_margin, delta_f1),                "compactness_f1_expected": None                if delta_compact is None or delta_f1 is None                else int((delta_compact < 0 and delta_f1 > 0) or (delta_compact > 0 and delta_f1 < 0)),                "chain_supported": None                if None in (delta_compact, delta_intra, delta_margin, delta_f1)                else int(delta_compact < 0 and delta_intra < 0 and delta_margin > 0 and delta_f1 > 0),                "chain_contradicted": None                if None in (delta_compact, delta_intra, delta_margin, delta_f1)                else int(delta_compact < 0 and delta_intra < 0 and delta_margin <= 0),            }        )    return rowsdef summarize_chain(chain_rows):    grouped = {}    for row in chain_rows:        grouped.setdefault(row["task"], []).append(row)    out = []    for task, rows in sorted(grouped.items()):        out.append(            {                "task": task,                "n": len(rows),                "delta_da_f1_mean": mean([row["delta_da_f1"] for row in rows]),                "delta_da_f1_std": stdev([row["delta_da_f1"] for row in rows]),                "delta_source_raw_compactness_mean": mean(                    [row["delta_source_raw_compactness"] for row in rows]                ),                "delta_source_pooled_intra_variance_mean": mean(                    [row["delta_source_pooled_intra_variance"] for row in rows]                ),                "delta_target_to_source_margin_mean": mean(                    [row["delta_target_to_source_margin"] for row in rows]                ),                "compactness_reduced_count": sum(row["compactness_reduced"] == 1 for row in rows),                "intra_variance_reduced_count": sum(row["intra_variance_reduced"] == 1 for row in rows),                "margin_increased_count": sum(row["margin_increased"] == 1 for row in rows),                "margin_f1_same_direction_count": sum(                    row["margin_f1_same_direction"] == 1 for row in rows                ),                "chain_supported_count": sum(row["chain_supported"] == 1 for row in rows),                "chain_contradicted_count": sum(row["chain_contradicted"] == 1 for row in rows),            }        )    return outdef parse_args():    parser = argparse.ArgumentParser(        description="Paired causal-chain diagnostic for v2.4.3b raw compactness."    )    parser.add_argument("--jobs_tsv", required=True)    parser.add_argument("--summary_tsv", required=True)    parser.add_argument("--output_dir", required=True)    parser.add_argument("--data_root", default="/data/user/DBL/timematch_data")    parser.add_argument("--outputs_root", default="outputs")    parser.add_argument("--source_tag_prefix", default="v243b_stage")    parser.add_argument("--tasks", default="FR2_to_FR1,DK1_to_FR1")    parser.add_argument("--seeds", default="1,2,3")    parser.add_argument("--base_config", default="plain")    parser.add_argument("--shaped_config", default="raw_global_w1_source_only")    parser.add_argument("--device", default="cuda")    parser.add_argument("--batch_size", type=int, default=128)    parser.add_argument("--num_workers", type=int, default=8)    parser.add_argument("--max_batches", type=int, default=64)    parser.add_argument("--model", default="pseltae", choices=["pseltae", "psetae", "psetcnn", "psegru"])    parser.add_argument("--with_extra", action="store_true")    return parser.parse_args()def main():    args = parse_args()    device = torch.device(args.device)    jobs = read_jobs_tsv(args.jobs_tsv)    pairs = task_seed_pairs(jobs, args.tasks, args.seeds, args.base_config, args.shaped_config)    if not pairs:        raise SystemExit("No complete base/shaped pairs found in jobs_tsv.")    metric_rows = []    seen = set()    total_jobs = len(pairs) * 2    for idx, (base, shaped) in enumerate(pairs, start=1):        for row in (base, shaped):            key = (row["task"], row["seed"], row["config"])            if key in seen:                continue            seen.add(key)            print(                f"[{len(seen)}/{total_jobs}] task={row['task']} seed={row['seed']} config={row['config']}",                flush=True,            )            metric_rows.append(compute_metrics_for_job(row, args, device))    summary_rows = read_tsv(args.summary_tsv)    chain_rows = build_chain_rows(metric_rows, summary_rows, args)    output_dir = Path(args.output_dir)    metric_fields = [        "task",        "seed",        "config",        "status",        "source_count",        "target_count",        "source_raw_compactness",        "source_pooled_intra_variance",        "target_to_source_margin",        "checkpoint",    ]    chain_fields = [        "task",        "seed",        "base_config",        "shaped_config",        "base_da_f1",        "shaped_da_f1",        "delta_da_f1",        "delta_source_raw_compactness",        "delta_source_pooled_intra_variance",        "delta_target_to_source_margin",        "compactness_reduced",        "intra_variance_reduced",        "margin_increased",        "margin_f1_same_direction",        "compactness_f1_expected",        "chain_supported",        "chain_contradicted",    ]    summary_fields = [        "task",        "n",        "delta_da_f1_mean",        "delta_da_f1_std",        "delta_source_raw_compactness_mean",        "delta_source_pooled_intra_variance_mean",        "delta_target_to_source_margin_mean",        "compactness_reduced_count",        "intra_variance_reduced_count",        "margin_increased_count",        "margin_f1_same_direction_count",        "chain_supported_count",        "chain_contradicted_count",    ]    write_tsv(output_dir / "paired_geometry_metrics.tsv", metric_rows, metric_fields)    write_tsv(output_dir / "paired_geometry_chain.tsv", chain_rows, chain_fields)    write_tsv(output_dir / "paired_geometry_chain_summary.tsv", summarize_chain(chain_rows), summary_fields)    print("Wrote:", output_dir / "paired_geometry_metrics.tsv")    print("Wrote:", output_dir / "paired_geometry_chain.tsv")    print("Wrote:", output_dir / "paired_geometry_chain_summary.tsv")if __name__ == "__main__":    main()